mapper.select:
SELECT  
WHERE r.tenant_id=#{tenant} AND r.id > #{q.after}
AND r.job_type=#{q.filters.jobType}
AND r.status=#{q.filters.status}
AND (r.status='RUNNING' AND r.lease_until <= #{at})=#{q.filters.leaseExpired}
AND r.created_at >= #{q.createdFrom} AND r.created_at < #{q.createdTo}
ORDER BY r.id ASC LIMIT #{q.fetchLimit}
